#define IF_NORM 512.238546f
// features order: ['rain_mm', 'rain_3d', 'dP_9to3', 'temp', 'humidity']. Returns anomaly score in (0,1]; higher = more anomalous.
static inline float if_score(const float *x) {
  float s = 0;
  for (int t = 0; t < IF_N_TREES; t++) {
    uint16_t b = IF_OFFSET[t], i = 0;
    while (IF_FEAT[b + i] >= 0)
      i = (x[IF_FEAT[b + i]] <= IF_THR[b + i]) ? i + 1 : IF_RIGHT[b + i];
    s += IF_THR[b + i];
  }
  return powf(2.0f, -s / IF_NORM);
}
